/**
 * TwelveLittleScoutsClerk per-event member payments report renderer
 *
 * Lists every participant of a single event and the amount that member paid
 * (bank transfer plus cash). Members who did not pay anything are kept in the
 * list with a 0 line, so the report always shows the complete event roster.
 *
 * @author Copyright (c) 2026 Martin Oberzalek
 */
// generated by AI (GitHub Copilot / Claude Sonnet 4.6)
package at.redeye.twelvelittlescoutsclerk.reports.eventpayments;

import at.redeye.FrameWork.base.AutoLogger;
import at.redeye.FrameWork.base.bindtypes.DBDouble;
import at.redeye.FrameWork.base.bindtypes.DBString;
import at.redeye.FrameWork.base.reports.BaseReportRenderer;
import at.redeye.FrameWork.base.reports.ReportRenderer;
import at.redeye.FrameWork.base.transaction.Transaction;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBBillingPeriod;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBEvent;
import at.redeye.twelvelittlescoutsclerk.bindtypes.DBEventMember;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

// AI-generated start (GitHub Copilot / Claude Sonnet 4.6)
public class ReportEventPaymentsRenderer extends BaseReportRenderer implements ReportRenderer {

    private static final Locale MONEY_LOCALE = Locale.GERMANY;

    /** One member row of the report. Amounts are kept even when they are 0. */
    public static class Row {

        private final String forname;
        private final String name;
        private final String group;
        private final double costs;
        private final double paid;
        private final double paidCash;

        Row(String forname, String name, String group, double costs, double paid, double paidCash) {
            this.forname = forname;
            this.name = name;
            this.group = group;
            this.costs = costs;
            this.paid = paid;
            this.paidCash = paidCash;
        }

        public String getForname() {
            return forname;
        }

        public String getName() {
            return name;
        }

        /** "Forname Name" without leading/trailing blanks. */
        public String getDisplayName() {
            return (forname + " " + name).trim();
        }

        public String getGroup() {
            return group;
        }

        /** Amount the member is supposed to pay. */
        public double getCosts() {
            return costs;
        }

        /** Amount paid by bank transfer. */
        public double getPaid() {
            return paid;
        }

        /** Amount paid in cash. */
        public double getPaidCash() {
            return paidCash;
        }

        public double getTotalPaid() {
            return paid + paidCash;
        }

        /** Open amount: costs - total paid (can be negative for overpayments). */
        public double getOpen() {
            return costs - getTotalPaid();
        }
    }

    private final Transaction trans;
    private final DBBillingPeriod bp;
    private final DBEvent event;

    private final List<Row> rows = new ArrayList<>();
    private String eventName = "";
    private double feePerPerson = 0.0;

    public ReportEventPaymentsRenderer(Transaction trans, DBBillingPeriod bp, DBEvent event) {
        this.trans = trans;
        this.bp = bp;
        this.event = event;
    }

    @Override
    public boolean collectData() {
        AutoLogger al = new AutoLogger(ReportEventPaymentsRenderer.class.getSimpleName()) {
            @Override
            public void do_stuff() throws Exception {
                collect();
            }
        };
        return !al.isFailed();
    }

    @Override
    public String render() {
        AutoLogger al = new AutoLogger(ReportEventPaymentsRenderer.class.getSimpleName()) {
            @Override
            public void do_stuff() throws Exception {
                result = doRender();
            }
        };
        if (al.result instanceof String) {
            return (String) al.result;
        }
        return "<html><body>Error generating report</body></html>";
    }

    private void collect() throws Exception {
        rows.clear();
        eventName = event != null && event.name != null ? event.name.toString() : "";
        feePerPerson = event != null && event.costs != null && event.costs.getValue() != null
                ? event.costs.getValue() : 0.0;

        if (event == null) {
            return;
        }

        DBEventMember emProto = new DBEventMember();
        List<DBEventMember> members = trans.fetchTable2(emProto,
                "where " + trans.markColumn(emProto.bp_idx) + " = " + event.bp_idx.toString()
                + " and " + trans.markColumn(emProto.event_idx) + " = " + event.idx.toString()
                + " order by " + trans.markColumn(emProto.name)
                + ", " + trans.markColumn(emProto.forname));

        for (DBEventMember em : members) {
            rows.add(new Row(
                    text(em.forname),
                    text(em.name),
                    text(em.group),
                    value(em.costs),
                    value(em.paid),
                    value(em.paid_cash)));
        }
    }

    private String doRender() {
        clear();
        html_start();
        html_setTitle("Event Payments — " + eventName
                + (bp != null && bp.title != null ? " (" + bp.title.toString() + ")" : ""));

        text.append("<p><b>Event:</b> ").append(escapeHtml(eventName)).append("<br/>")
                .append("<b>Participants:</b> ").append(rows.size()).append("<br/>")
                .append("<b>Fee per person:</b> ").append(money(feePerPerson)).append(" €</p>");

        text.append("<table border='1' cellpadding='4' cellspacing='0' style='border-collapse:collapse;'>");
        text.append("<tr>")
                .append("<th align='left'>#</th>")
                .append("<th align='left'>Name</th>")
                .append("<th align='left'>Group</th>")
                .append("<th align='right'>Costs (€)</th>")
                .append("<th align='right'>Paid (€)</th>")
                .append("<th align='right'>Paid cash (€)</th>")
                .append("<th align='right'>Total paid (€)</th>")
                .append("<th align='right'>Open (€)</th>")
                .append("</tr>");

        int number = 1;
        for (Row row : rows) {
            text.append("<tr>")
                    .append("<td>").append(number).append("</td>")
                    .append("<td>").append(escapeHtml(row.getDisplayName())).append("</td>")
                    .append("<td>").append(escapeHtml(row.getGroup())).append("</td>")
                    .append("<td align='right'>").append(money(row.getCosts())).append("</td>")
                    .append("<td align='right'>").append(money(row.getPaid())).append("</td>")
                    .append("<td align='right'>").append(money(row.getPaidCash())).append("</td>")
                    .append("<td align='right'>").append(money(row.getTotalPaid())).append("</td>")
                    .append("<td align='right'>").append(money(row.getOpen())).append("</td>")
                    .append("</tr>");
            number++;
        }

        if (rows.isEmpty()) {
            text.append("<tr><td colspan='8'>no participants</td></tr>");
        }

        text.append("<tr style='font-weight:bold'>")
                .append("<td></td>")
                .append("<td>Total</td>")
                .append("<td></td>")
                .append("<td align='right'>").append(money(getTotalCosts())).append("</td>")
                .append("<td align='right'>").append(money(getTotalPaidBank())).append("</td>")
                .append("<td align='right'>").append(money(getTotalPaidCash())).append("</td>")
                .append("<td align='right'>").append(money(getTotalPaid())).append("</td>")
                .append("<td align='right'>").append(money(getTotalOpen())).append("</td>")
                .append("</tr>");

        text.append("</table>");

        html_stop();
        return text.toString();
    }

    private static String text(DBString value) {
        return value != null && value.getValue() != null ? value.getValue() : "";
    }

    private static double value(DBDouble value) {
        return value != null && value.getValue() != null ? value.getValue() : 0.0;
    }

    private static String money(double value) {
        return String.format(MONEY_LOCALE, "%,.2f", value);
    }

    private static String escapeHtml(String s) {
        if (s == null) {
            return "";
        }
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    // ------------------------------------------------------------------
    // getters (used by the ODS export)
    // ------------------------------------------------------------------
    public List<Row> getRows() {
        return new ArrayList<>(rows);
    }

    public String getEventName() {
        return eventName;
    }

    public DBBillingPeriod getBillingPeriod() {
        return bp;
    }

    public int getParticipantCount() {
        return rows.size();
    }

    public double getFeePerPerson() {
        return feePerPerson;
    }

    public double getTotalCosts() {
        double sum = 0.0;
        for (Row row : rows) {
            sum += row.getCosts();
        }
        return sum;
    }

    public double getTotalPaidBank() {
        double sum = 0.0;
        for (Row row : rows) {
            sum += row.getPaid();
        }
        return sum;
    }

    public double getTotalPaidCash() {
        double sum = 0.0;
        for (Row row : rows) {
            sum += row.getPaidCash();
        }
        return sum;
    }

    public double getTotalPaid() {
        double sum = 0.0;
        for (Row row : rows) {
            sum += row.getTotalPaid();
        }
        return sum;
    }

    public double getTotalOpen() {
        double sum = 0.0;
        for (Row row : rows) {
            sum += row.getOpen();
        }
        return sum;
    }
}
// AI-generated end
